def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    fixed_eric_like = []
    high_spenders = []

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if abs(float(bid) - 63.0) <= 0.01:
                    fixed_eric_like.append(opp)
                if float(bid) >= 100.0:
                    high_spenders.append(opp)

    if not alive_opponents:
        return max(0.0, min(budget, 20.0))

    severe_need = hp <= 3 or no_water_days >= 2
    urgent_need = hp <= 5 or no_water_days >= 1
    scarce = supply <= 17
    abundant = supply >= 22

    target = 0.0

    if severe_need:
        if prev_bids:
            target = max(prev_bids) + 2.0
        else:
            target = 66.0
    elif urgent_need:
        if scarce:
            if prev_bids:
                target = max(64.5, min(max(prev_bids) + 1.0, 82.0))
            else:
                target = 65.0
        else:
            target = 64.5 if fixed_eric_like else 49.0
    else:
        if abundant:
            target = 18.0
        elif scarce:
            target = 64.5 if fixed_eric_like else 42.0
        else:
            target = 28.0 if high_spenders else 52.0

    if day >= 8:
        target += 4.0
    if day >= 9 and urgent_need:
        target += 6.0

    max_safe = budget
    if hp > 6 and no_water_days == 0:
        max_safe = min(max_safe, DAILY_SALARY * 0.95)
    else:
        max_safe = min(max_safe, DAILY_SALARY * 1.35)

    bid = min(max_safe, target)
    if budget <= 0:
        return 0.0
    if bid < 0:
        bid = 0.0
    return float(round(min(budget, bid), 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_active_opponents = len(alive_opponents)

    if not alive_opponents:
        if day_context['supply'] >= WATER_REQ:
            return min(my_status['budget'], DAILY_SALARY * 0.1)
        else:
            return min(my_status['budget'], DAILY_SALARY * 0.4)

    bid = DAILY_SALARY * 0.5

    if my_status['hp'] <= 2 or my_status['no_water_days'] > 0:
        bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4:
        bid = DAILY_SALARY * 0.75

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2:
        bid = max(bid, DAILY_SALARY * 0.9)
    elif remaining_days <= 4:
        bid = max(bid, DAILY_SALARY * 0.7)

    if day_context['supply'] < WATER_REQ:
        bid = max(bid, DAILY_SALARY * 0.6)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 3 and remaining_days > 2 and day_context['supply'] >= WATER_REQ * (num_active_opponents + 1):
                bid = min(bid, DAILY_SALARY * 0.6)
            else:
                bid = max(bid, highest_prev_bid + 5)
        elif highest_prev_bid >= DAILY_SALARY * 0.5:
            bid = max(bid, highest_prev_bid + 1)
        else:
            bid = max(bid, highest_prev_bid * 1.1)
            bid = min(bid, DAILY_SALARY * 0.6)

    bid = min(bid, my_status['budget'])
    bid = max(bid, 0.0)

    if (my_status['hp'] <= 2 or my_status['no_water_days'] > 0) and my_status['budget'] > 0:
        bid = max(bid, 1.0)

    if bid == 0.0 and my_status['budget'] > 0 and day_context['supply'] > 0:
        bid = 0.1

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = int(day_context['supply'])
    max_water_units = supply // WATER_REQ
    prev_bids = []
    for oid, opp in opponents_status.items():
        if opp.get('alive') and opp.get('previous_trace') and opp['previous_trace'].get('bid') is not None:
            prev_bids.append(opp['previous_trace']['bid'])
    if prev_bids:
        sorted_bids = sorted(prev_bids, reverse=True)
        num_units = min(max_water_units, len(sorted_bids))
        if num_units > 0:
            target = sum(sorted_bids[:int(num_units)]) / num_units
        else:
            target = DAILY_SALARY * 0.5
        if my_status['hp'] < 3:
            target = target * 1.2 + 1
        elif my_status['hp'] > 6:
            target = target * 0.8
        else:
            target = target * 1.0
        bid = min(my_status['budget'], target)
        bid = max(1, bid)
    else:
        if my_status['hp'] < 3:
            bid = min(my_status['budget'], DAILY_SALARY * 0.9)
        else:
            bid = min(my_status['budget'], DAILY_SALARY * 0.5)
    return bid
